\vspace{-0.1cm}

To begin with, we have the following equations for the complex-valued partial derivative in terms a real value \cite{hjorungnes2007complex}
\begin{flalign} \label{FIM_Derivation}
  &\frac{\partial(a+jb)e^{jc}}{\partial a} = e^{jc},~
  \frac{\partial(a+jb)e^{jc}}{\partial b} = je^{jc}. 
\end{flalign}
Then, we can calculate the partial derivative related to the real and imaginary parts of RCS as 
\begin{subequations} 
\label{FIM_Derivation_RCS}
\begin{align} 
 & \frac{\partial{\bf A}_{k,m}{\bf x}_{k,m}}{\partial\alpha_{R_{q}}} =  {\bf a}_{\mathrm{R}}(k,m,q){\bf a}^T_{\mathrm{T}}(k,m,q){\bf x}_{k,m}, \label{FIM_Derivation_RCS1}\\
& \frac{\partial{\bf A}_{k,m}{\bf x}_{k,m}}{\partial\alpha_{I_{q}}} = j {\bf a}_{\mathrm{R}}(k,m,q){\bf a}^T_{\mathrm{T}}(k,m,q){\bf x}_{k,m}.\label{FIM_Derivation_RCS2}
\end{align}
\end{subequations}
where $q=1,\cdots,Q$.
According to Cauchy-Riemann equations, we have  \cite{hjrungnes2011complex}
\begin{subequations} \label{FIM_RCS}
\begin{align} 
  \frac{\partial{\bf A}_{k,m}{\bf x}_{k,m}}{\partial{\bm\alpha}_{R}} &= [\breve{\bf A}_{k,m}(1){\bf x}_{k,m},\cdots,\breve{\bf A}_{k,m}(Q){\bf x}_{k,m}],  \label{FIM_RCS_Re}\\
  \frac{\partial{\bf A}_{k,m}{\bf x}_{k,m}}{\partial{\bm\alpha}_{I}} &= j[\breve{\bf A}_{k,m}(1){\bf x}_{k,m},\cdots,\breve{\bf A}_{k,m}(Q){\bf x}_{k,m}],   \label{FIM_RCS_Im}
\end{align}
\end{subequations}
where $\breve{\bf A}_{k,m}(q)={\bf A}_{\mathrm{R},k,m}{\bf \Lambda}_{q} {\bf A}_{\mathrm{T},k,m}^T$ denotes the partial derivative matrix and ${\bf \Lambda}_{q}$ denotes the selection matrix with $q$-th diagonal element is one and the others are zero. Substituting \eqref{FIM_RCS} into \eqref{FIM_wide-band} and \eqref{FIM_spe}, we can get the wide-band CRB for RCS estimation as \cite{liang2021CramerRao} 
\begin{small}
\begin{align} \label{CRB_resp.2.2}
&\mathrm{CRB}_{\alpha_{R_{q}}} \!=\!\mathrm{CRB}_{\alpha_{I_{q}}} \nonumber \\
= &\frac{\sigma_r^2}{2\mathbb{E}\{{\sum}_{k=1}^K{\sum}_{m=1}^M\|{\bf a}_{\mathrm{R}}(k,m,q){\bf a}_{\mathrm{T}}^{T}(k,m,q){\bf x}_{k,m}\|_2^2\}}. 
\end{align}
\end{small}
Then, we have $\mathrm{CRB}_{\alpha_{R_{q}}}=\mathrm{CRB}_{\alpha_q}+\mathrm{CRB}_{\alpha_{I_{q}}}$.






\vspace{-0.2cm}

\vspace{-0.1cm}
Similarly, the velocity part is 
\begin{subequations} \label{Derivation_vel.}
\begin{align} 
  \frac{\partial{\bf A}_{k,m}{\bf x}_{k,m}}{\partial{\bf v}_x} &
  = [\acute{\bf A}_{k,m}(1){\bf x}_{k,m},\cdots,\acute{\bf A}_{k,m}(Q){\bf x}_{k,m}], \label{Derivation_vel.1} \\
  \frac{\partial{\bf A}_{k,m}{\bf x}_{k,m}}{\partial{\bf v}_y} &
  =[\grave{\bf A}_{k,m}(1){\bf x}_{k,m},\cdots,\grave{\bf A}_{k,m}(Q){\bf x}_{k,m}], \label{Derivation_vel.2}
\end{align}
\end{subequations}
where $\acute{\bf A}_{k,m}(q)=[{\acute{\bf A}_{\mathrm{R},k,m}}{\bf \Lambda}_{q} {\bf B}{\bf A}_{\mathrm{T},k,m}^T+{\bf A}_{\mathrm{R},k,m}{\bf B}{\bf \Lambda}_{q}{\acute{\bf A}_{\mathrm{T},k,m}^T}]$ and $\grave{\bf A}_{k,m}(q)$ denotes the partial derivative of ${\bf A}_{k,m}$ w.r.t. $v_{x_q}$ and $v_{y_q}$, respectively, in which any of these is given  
\begin{align*} 
\frac{\partial{\bf a}_{\mathrm{R},\mathrm{T},\ast}(k,m,q) }{\partial v_{x_q}}&= \frac{j2\pi\frac{f_k}{c}mT_{\mathrm{sym}}({x}_q-{x}_{\ast})}{{\|{\mathbb I}_{q}-{\mathbb I}_{\ast}\|}}{\bf a}_{\mathrm{R},\mathrm{T},\ast}(k,m,q)\\
\frac{\partial{\bf a}_{\mathrm{R},\mathrm{T},\ast}(k,m,q) }{\partial v_{y_q}}&= \frac{j2\pi\frac{f_k}{c}mT_{\mathrm{sym}}({y}_q-{y}_{\ast})}{{\|{\mathbb I}_{q}-{\mathbb I}_{\ast}\|}}{\bf a}_{\mathrm{R},\mathrm{T},\ast}(k,m,q).
\end{align*}
Substituting \eqref{Derivation_vel.} into \eqref{FIM_spe} and \eqref{FIM_wide-band}, the CRB related to the velocity estimation of $q$-th target is 
\begin{subequations} \label{CRB_vel.q}
\begin{align}
 \mathrm{CRB}_{v_{x_q}}&= \frac{\sigma_r^2}{2\mathbb{E}\{\sum_{k=1}^K\sum_{m=1}^M\|\acute{\bf A}_{k,m}(q){\bf x}_{k,m}\|_2^2\}} ,    \label{CRB_vel.q1}\\
 \mathrm{CRB}_{v_{y_q}}& = \frac{\sigma_r^2}{2\mathbb{E}\{\sum_{k=1}^K\sum_{m=1}^M\|\grave{\bf A}_{k,m}(q){\bf x}_{k,m}\|_2^2\}}. \label{CRB_vel.q2}

\end{align}
\end{subequations}





\vspace{-0.2cm}

\vspace{-0.1cm}

Similarly, for the partial derivative w.r.t location, we have 
\begin{subequations} \label{Derivation_loc.}
\begin{align} 
  \frac{\partial{\bf A}_{k,m}{\bf x}_{k,m}}{\partial{\bf x}} &=[\ddot{\bf A}_{k,m}(1){\bf x}_{k,m},\cdots,\ddot{\bf A}_{k,m}(Q){\bf x}_{k,m}], \label{Derivation_loc.1}\\
  \frac{\partial{\bf A}_{k,m}{\bf x}_{k,m}}{\partial{\bf y}} & =[\dot{\bf A}_{k,m}(1){\bf x}_{k,m},\cdots,\dot{\bf A}_{k,m}(Q){\bf x}_{k,m}], \label{Derivation_loc.2}
\end{align}
\end{subequations}
where $\ddot{\bf A}_{k,m}(q)=[{\ddot{\bf A}_{\mathrm{R},k,m}}{\bf \Lambda}_{q} {\bf B}{\bf A}_{\mathrm{T},k,m}^T+{\bf A}_{\mathrm{R},k,m}{\bf B}{\bf \Lambda}_{q}{\ddot{\bf A}_{\mathrm{T},k,m}^T}]$ and $\dot{\bf A}_{k,m}(q)=[{\dot{\bf A}_{\mathrm{R},k,m}}{\bf \Lambda}_{q} {\bf B}{\bf A}_{\mathrm{T},k,m}^T+{\bf A}_{\mathrm{R},k,m}{\bf B}{\bf \Lambda}_{q}{\dot{\bf A}_{\mathrm{T},k,m}^T}]$ denotes the partial derivative of ${\bf A}_{k,m}$ w.r.t. $x_q$ and $y_q$, respectively, with each element of the derivative w.r.t $x_q$ being $\frac{\partial{\bf a}_{\mathrm{R},\mathrm{T},\ast}(k,m,q) }{\partial{x_q}}= \ddot{g}_{\mathrm{R},\mathrm{T},\ast}(k,m,q) {\bf a}_{\mathrm{R},\mathrm{T},\ast}(k,m,q)$, where the gain $\ddot{g}_{\mathrm{R},\mathrm{T},\ast}(k,m,q)$ is given by \eqref{derivation_x} arranged at the top of next page

and each element of the derivation w.r.t $y_q$ can be similarly obtained. 
Substituting \eqref{Derivation_loc.} into \eqref{FIM_spe} and \eqref{FIM_wide-band}, lower bound on CRB of the location estimation for $q$-th target is 
\begin{subequations} \label{CRB_loc.q}
\begin{align}
 \mathrm{CRB}_{x_q}& = \frac{\sigma_r^2}{2\mathbb{E}\{\sum_{k=1}^K\sum_{m=1}^M\|\dot{\bf A}_{k,m}(q){\bf x}_{k,m}\|_2^2\}} ,    \\
 \mathrm{CRB}_{y_q}& = \frac{\sigma_r^2}{2\mathbb{E}\{\sum_{k=1}^K\sum_{m=1}^M\|\ddot{\bf A}_{k,m}(q){\bf x}_{k,m}\|_2^2\}}.
\end{align}
\end{subequations}










With the general CRB expressions given above, we can then explore the CRB for the specific cases. 




