We can first define the gains of Tx and Rx at the $k$-th subcarrier and $m$-th OFDM symbol, respectively, as
\begin{subequations} \label{gain_Tx_Rx}
 \begin{align} 
   G_{\mathrm{Tx}} &\!=\! \|{\bf a}_{\mathrm{T}}(k,m,q)\|_2^2 = \frac{\lambda_k^2}{16\pi^2}\sum_{n_t=1}^{N_t}\frac{1}{r_{n_t}^2} = \frac{\lambda_k^2}{16\pi^2}g_{\mathrm {Tx}}, \label{gain_Tx}\\ 
   G_{\mathrm{Rx}} &\!=\! \|{\bf a}_{\mathrm{R}}(k,m,q)\|_2^2 = \frac{\lambda_k^2}{16\pi^2}\sum_{n_r=1}^{N_r}\frac{1}{r_{n_r}^2} = \frac{\lambda_k^2}{16\pi^2}g_{\mathrm {Rx}}, \label{gain_Rx}
 \end{align}   
\end{subequations}
where $r_{n_t}=\|{\mathbb I}_{q}-{\mathbb I}_{n_t}\|$ and $r_{n_r}=\|{\mathbb I}_{q}-{\mathbb I}_{n_r}\|$. 
Then, we have 
\begin{flalign} \label{CRB_RCS}
\mathrm{CRB}_{\alpha_{R}}=\mathrm{CRB}_{\alpha_{I}}=\frac{256\sigma_r^2\pi^{4}}{2\mathcal{P}Mg_{\mathrm {Tx}}g_{\mathrm {Rx}}\widetilde{\bm\Lambda}}. 
\end{flalign} 
where $\widetilde{\bm\Lambda}_4=\sum_{k=1}^{K}\lambda_k^4$. 
